package de.taxil150.app;
import android.app.*;import android.os.*;import android.content.*;import android.webkit.*;import android.widget.*;import org.json.*;import java.io.*;
public class MainActivity extends Activity {
 String appVersion="";WebView web; boolean loaded;Handler h=new Handler();SharedPreferences p;boolean pendingTest;boolean previewRequested,callPreview;FlightRepository flights;WeatherRepository weather;PrayerRepository prayers;CallHistory history;CountdownStore countdown;boolean historyVisible;int historyOffset;boolean flightsVisible;
 boolean isRealCall(){return "AUFGERUFEN!".equals(p.getString("state",""));}
 Runnable testTask=()->{if(previewRequested&&isRealCall()){previewRequested=false;render();return;}callPreview=previewRequested;previewRequested=false;Alerts.post(this,p.getString("number","L150"),"",true);render();};
 Runnable update=new Runnable(){public void run(){render();h.postDelayed(this,1000);}};
 public void onCreate(Bundle b){super.onCreate(b);try{appVersion=getPackageManager().getPackageInfo(getPackageName(),0).versionName;}catch(Exception ignored){}p=getSharedPreferences("status",0);flights=new FlightRepository(this,()->render());weather=new WeatherRepository(this,()->render());prayers=new PrayerRepository(this,()->render());history=new CallHistory(this);countdown=new CountdownStore(this);Alerts.ensure(this);web=new WebView(this);WindowAppearance.attach(this,web);web.getSettings().setJavaScriptEnabled(true);web.getSettings().setAllowFileAccess(false);web.getSettings().setAllowContentAccess(false);web.getSettings().setMixedContentMode(WebSettings.MIXED_CONTENT_NEVER_ALLOW);web.addJavascriptInterface(new Bridge(),"TaxiAndroid");web.setWebViewClient(new WebViewClient(){public void onPageFinished(WebView v,String url){loaded=true;render();}public boolean shouldOverrideUrlLoading(WebView v,WebResourceRequest r){return true;}public WebResourceResponse shouldInterceptRequest(WebView v,WebResourceRequest r){if(!r.getUrl().toString().startsWith("file:///android_asset/"))return new WebResourceResponse("text/plain","UTF-8",new ByteArrayInputStream(new byte[0]));return null;}});web.loadUrl("file:///android_asset/index.html");if(p.getString("monitor","Aus").equals("Aktiv")&&!MonitorService.running)start();}
 void save(String raw){try{String number=Config.normalize(raw);synchronized(Config.LOCK){String old=p.getString("number","L150");if(!number.equals(old)){SharedPreferences.Editor e=p.edit().putString("number",number).putString("state","Noch nicht geladen").putString("connection","Warte auf nächsten Abruf").remove("updatedAt");for(String k:new String[]{"rank","points","firstPoints","total","lCount","mCount","target","time"})e.remove(k);if(!e.commit())throw new IllegalStateException("Speichern fehlgeschlagen");getSystemService(NotificationManager.class).cancel(2);if(p.getString("monitor","Aus").equals("Aktiv"))startForegroundService(new Intent(this,MonitorService.class));}}render();}catch(Exception e){Toast.makeText(this,e.getMessage(),Toast.LENGTH_LONG).show();}}
 void start(){if(Build.VERSION.SDK_INT>=33&&checkSelfPermission("android.permission.POST_NOTIFICATIONS")!=android.content.pm.PackageManager.PERMISSION_GRANTED){requestPermissions(new String[]{"android.permission.POST_NOTIFICATIONS"},1);return;}try{startForegroundService(new Intent(this,MonitorService.class));}catch(Exception e){Toast.makeText(this,"Start nicht möglich: "+e.getMessage(),Toast.LENGTH_LONG).show();}}
 public void onRequestPermissionsResult(int request,String[] permissions,int[] results){super.onRequestPermissionsResult(request,permissions,results);if(request==1&&results.length>0&&results[0]==android.content.pm.PackageManager.PERMISSION_GRANTED)start();if(request==2){if(results.length>0&&results[0]==android.content.pm.PackageManager.PERMISSION_GRANTED&&pendingTest)scheduleTest();else {previewRequested=false;p.edit().putString("testAlarm","Blockiert: Benachrichtigungsberechtigung nicht erteilt").apply();}pendingTest=false;render();}}

 void test(){if(Build.VERSION.SDK_INT>=33&&checkSelfPermission("android.permission.POST_NOTIFICATIONS")!=android.content.pm.PackageManager.PERMISSION_GRANTED){pendingTest=true;requestPermissions(new String[]{"android.permission.POST_NOTIFICATIONS"},2);return;}scheduleTest();}
 void scheduleTest(){if(!Alerts.blocked(this).isEmpty()){previewRequested=false;p.edit().putString("testAlarm","Blockiert: "+Alerts.blocked(this)).apply();startActivity(Alerts.settings(this));return;}p.edit().putString("testAlarm","Testalarm in 5 Sekunden – jetzt Bildschirm sperren möglich").apply();Toast.makeText(this,"Testalarm in 5 Sekunden",Toast.LENGTH_SHORT).show();h.removeCallbacks(testTask);h.postDelayed(testTask,5000);render();}
 class Bridge {
  @JavascriptInterface public void contactEmail(){h.post(()->{android.net.Uri uri=android.net.Uri.parse("mailto:feridunbln@gmail.com?subject="+android.net.Uri.encode("Taxi Monitor – Rückmeldung"));try{startActivity(new Intent(Intent.ACTION_SENDTO,uri));}catch(Exception e){Toast.makeText(MainActivity.this,"Keine E-Mail-App verfügbar. Kontakt: feridunbln@gmail.com",Toast.LENGTH_LONG).show();}});}

  @JavascriptInterface public void tariffSource(String which){h.post(()->{String url="law".equals(which)?"https://gesetze.berlin.de/bsbe/?docId=jlr-NNLBE00004AA2NN00000000029":"https://www.taxi-berlin.de/taxitarif/";try{startActivity(new Intent(Intent.ACTION_VIEW,android.net.Uri.parse(url)));}catch(Exception e){Toast.makeText(MainActivity.this,"Kein Browser verfügbar",Toast.LENGTH_SHORT).show();}});}

  @JavascriptInterface public void timerToggle(){h.post(()->{try{countdown.toggle();render();}catch(Exception e){Toast.makeText(MainActivity.this,e.getMessage(),Toast.LENGTH_LONG).show();}});}
  @JavascriptInterface public void timerReset(){h.post(()->{try{countdown.reset();render();}catch(Exception e){Toast.makeText(MainActivity.this,e.getMessage(),Toast.LENGTH_LONG).show();}});}

  @JavascriptInterface public void showHistory(int offset){h.post(()->{historyVisible=true;historyOffset=Math.max(0,offset);render();});}
  @JavascriptInterface public void hideHistory(){h.post(()->historyVisible=false);}
  @JavascriptInterface public void prayerSource(){h.post(()->{try{startActivity(new Intent(Intent.ACTION_VIEW,android.net.Uri.parse(PrayerRepository.WEBSITE)));}catch(Exception e){Toast.makeText(MainActivity.this,"Kein Browser verfügbar",Toast.LENGTH_SHORT).show();}});}

  @JavascriptInterface public void weatherSource(){h.post(()->{try{startActivity(new Intent(Intent.ACTION_VIEW,android.net.Uri.parse("https://brightsky.dev/")));}catch(Exception e){Toast.makeText(MainActivity.this,"Kein Browser verfügbar",Toast.LENGTH_SHORT).show();}});}
  @JavascriptInterface public void showFlights(){h.post(()->{flightsVisible=true;flights.start();render();});}
  @JavascriptInterface public void hideFlights(){h.post(()->{flightsVisible=false;flights.stop();});}
  @JavascriptInterface public void refreshFlights(String date){h.post(()->{if(flightsVisible)flights.refresh(date);});}
  @JavascriptInterface public void officialFlights(){h.post(()->{try{startActivity(new Intent(Intent.ACTION_VIEW,android.net.Uri.parse(FlightRepository.WEBSITE)));}catch(Exception e){Toast.makeText(MainActivity.this,"Kein Browser verfügbar",Toast.LENGTH_SHORT).show();}});}
  @JavascriptInterface public void saveNumber(String n){h.post(()->save(n));}
  @JavascriptInterface public void startMonitor(){h.post(()->start());}
  @JavascriptInterface public void stopMonitor(){h.post(()->{stopService(new Intent(MainActivity.this,MonitorService.class));p.edit().putString("monitor","Aus").apply();render();});}
  @JavascriptInterface public void confirmCall(){h.post(()->{if(callPreview){callPreview=false;getSystemService(NotificationManager.class).cancel(3);render();return;}getSystemService(NotificationManager.class).cancel(2);p.edit().putString("acknowledgedKey",p.getString("detectedKey","" )).apply();render();});}
  @JavascriptInterface public void settings(){h.post(()->startActivity(Alerts.settings(MainActivity.this)));}
  @JavascriptInterface public void testAlarm(){h.post(()->{previewRequested=false;test();});}
  @JavascriptInterface public void testCall(){h.post(()->{if(isRealCall()){Toast.makeText(MainActivity.this,"Ein echter Aufruf ist aktiv",Toast.LENGTH_SHORT).show();return;}previewRequested=true;test();});}
 }
 void render(){if(!loaded)return;if(callPreview&&isRealCall()){callPreview=false;getSystemService(NotificationManager.class).cancel(3);}try{JSONObject obj=new JSONObject().put("version",appVersion);synchronized(Config.LOCK){obj.put("number",p.getString("number","L150"));for(String k:new String[]{"state","rank","points","firstPoints","total","lCount","mCount","target","connection","time","monitor","callTime","lastDetected","lastAlarm","testAlarm"})obj.put(k,p.getString(k,k.equals("state")?"Noch nicht geladen":k.equals("monitor")?"Aus":k.equals("connection")?"Nicht gestartet":"–"));}obj.put("monitor",MonitorService.running?"Aktiv":"Aus");obj.put("acknowledged",!p.getString("detectedKey","").isEmpty()&&p.getString("detectedKey","").equals(p.getString("acknowledgedKey","")));obj.put("updatedAt",p.getLong("updatedAt",0));if(flightsVisible)obj.put("flights",flights.state());obj.put("weather",weather.state());obj.put("prayers",prayers.state());try{obj.put("countdown",countdown.state());}catch(Exception e){obj.put("countdown",new JSONObject().put("error","Timer nicht verfügbar"));}if(historyVisible){try{obj.put("history",history.page(historyOffset).put("error",p.getString("historyError","")));}catch(Exception e){obj.put("history",new JSONObject().put("error","Aufrufverlauf derzeit nicht lesbar").put("items",new JSONArray()).put("count",0).put("offset",0));}}obj.put("preview",callPreview);obj.put("previewPending",previewRequested);if(callPreview){obj.put("state","AUFGERUFEN!");obj.put("target","1N");obj.put("acknowledged",false);}obj.put("alertStatus",Alerts.diagnostics(this));obj.put("tone",Alerts.tone(this));obj.put("vibration",getSystemService(NotificationManager.class).getNotificationChannel(Alerts.CHANNEL).shouldVibrate()?"Ein":"Aus");web.evaluateJavascript("window.renderNative("+obj.toString()+")",null);}catch(JSONException ignored){}}
 @Override public void onBackPressed(){if(loaded)web.evaluateJavascript("window.closeSettings()",handled->{if(!"true".equals(handled))finish();});else finish();}
 public void onResume(){super.onResume();getWindow().addFlags(android.view.WindowManager.LayoutParams.FLAG_KEEP_SCREEN_ON);weather.start();prayers.start();if(flightsVisible)flights.start();h.post(update);}public void onPause(){getWindow().clearFlags(android.view.WindowManager.LayoutParams.FLAG_KEEP_SCREEN_ON);prayers.stop();weather.stop();h.removeCallbacks(update);flights.stop();super.onPause();}public void onDestroy(){prayers.stop();history.close();weather.stop();loaded=false;flights.stop();h.removeCallbacksAndMessages(null);web.removeJavascriptInterface("TaxiAndroid");web.destroy();super.onDestroy();}
}
